const std = @import("std");

pub fn main() !void {
    const rows: usize = 5;
    var triangle: [5][5]u32 = undefined;

    for (0..rows) |i| {
        triangle[i][0] = 1;
        triangle[i][i] = 1;
        for (1..i) |j| {
            triangle[i][j] = triangle[i - 1][j - 1] + triangle[i - 1][j];
        }
    }

    for (0..rows) |i| {
        for (0..i + 1) |j| {
            std.debug.print("{} ", .{triangle[i][j]});
        }
        std.debug.print("\n", .{});
    }
}

